import { registerSW } from 'virtual:pwa-register';
import { markUpdateWaiting, setUpdateActivator } from './update';

/**
 * Registers the Workbox service worker that keeps the app shell available offline (generated by
 * vite-plugin-pwa; see vite.config.ts). It only ever fetches the app's own files from its own
 * origin. With registerType 'prompt', a new version waits until the person taps Reload.
 */

/** How often a reopened app checks for a new version, at most. */
const UPDATE_CHECK_INTERVAL_MS = 15 * 60 * 1000;

export function startServiceWorker(): void {
  if (!('serviceWorker' in navigator)) return;
  const updateServiceWorker = registerSW({
    onNeedRefresh: markUpdateWaiting,
    onRegisteredSW: (_url, registration) => {
      if (registration !== undefined) checkForUpdatesWhenReopened(registration);
    },
    onRegisterError: (error: unknown) => {
      console.warn('The offline copy of the app could not be set up.', error);
    },
  });
  setUpdateActivator(() => updateServiceWorker(true));
}

/**
 * The browser checks for a new version whenever the app is opened from scratch. An installed app
 * is often resumed from the background instead, so it also checks when it comes back into view.
 */
function checkForUpdatesWhenReopened(registration: ServiceWorkerRegistration): void {
  let lastCheck = Date.now();
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState !== 'visible' || !navigator.onLine) return;
    if (Date.now() - lastCheck < UPDATE_CHECK_INTERVAL_MS) return;
    lastCheck = Date.now();
    registration.update().catch(() => undefined);
  });
}
